from sqlalchemy import Column, Integer, DateTime, ForeignKey, Enum
from sqlalchemy.dialects.postgresql import UUID
from sqlalchemy.orm import relationship
import uuid
from .base import Base

class ProposalStatus(str):
    CANDIDATE = "candidate"
    SELECTED = "selected"

class RosterProposal(Base):
    """Roster proposals generated by the solver."""
    __tablename__ = "roster_proposal"
    
    id = Column(UUID(as_uuid=True), primary_key=True, default=uuid.uuid4)
    period_id = Column(UUID(as_uuid=True), ForeignKey("schedule_period.id", ondelete="CASCADE"), nullable=False)
    created_at = Column(DateTime(timezone=True), server_default="now()")
    soft_penalty_total = Column(Integer, nullable=False, default=0)
    hard_violation_count = Column(Integer, nullable=False, default=0)
    status = Column(Enum(ProposalStatus), nullable=False, default=ProposalStatus.CANDIDATE)
    
    # Relationships
    period = relationship("SchedulePeriod")
    assignments = relationship("Assignment", backref="proposal", foreign_keys="Assignment.proposal_id")
    violations = relationship("Violation", backref="proposal", foreign_keys="Violation.proposal_id")
    
    def __repr__(self):
        return f"<RosterProposal(id={self.id}, period={self.period_id}, penalty={self.soft_penalty_total}, hard_violations={self.hard_violation_count})>"
